import datetime


def _parse(timestamp):
    if timestamp.endswith('Z'):
        timestamp = timestamp[:-1] + '+00:00'
    return datetime.datetime.fromisoformat(timestamp)


def day_of_week(timestamp):
    """Return the weekday name for an ISO-8601 timestamp, as written."""
    return _parse(timestamp).strftime('%A')


def hours_between(start, end):
    """Whole hours from `start` to `end`, honoring timezone offsets."""
    delta = _parse(end) - _parse(start)
    return int(delta.total_seconds() // 3600)

